def assign_customers_to_routes(instance, depot, routes):
    unassigned_customers = set(instance.customer_ids)
    for cid in instance.customer_ids:
        if cid not in unassigned_customers:
            continue
        for route in routes:
            new_route = route + [cid, depot]
            states = propagate_route(instance, new_route)
            if all(state.battery_arrival >= 0 for state in states):
                routes.append(new_route)
                unassigned_customers.remove(cid)
                break
        else:
            # If no feasible route found, create a new one
            new_route = [depot, cid, depot]
            states = propagate_route(instance, new_route)
            if all(state.battery_arrival >= 0 for state in states):
                routes.append(new_route)
                unassigned_customers.remove(cid)
