    return route1[:-1] + route2[1:] + [instance.depot_id]

def insert_charging_station(instance, route):
    for station_id in instance.station_ids:
        for i in range(1, len(route)):
            new_route = route[:i] + [station_id] + route[i:]
            states = propagate_route(instance, new_route)
            if all(state.battery_arrival >= 0 for state in states) and not any(state.service_start > instance.node_map[state.node_id].due_time for state in states):
                return new_route
    return None

def optimize_route_with_charging(instance, route):
    states = propagate_route(instance, route)
    if all(state.battery_arrival >= 0 for state in states):
        return route

    best_route = None
    best_distance = float('inf')
    for station_id in instance.station_ids:
        for i in range(1, len(route)):
            new_route = route[:i] + [station_id] + route[i:]
            new_states = propagate_route(instance, new_route)
            if all(state.battery_arrival >= 0 for state in new_states):
                new_distance = sum(distance(instance.node_map[new_route[j]], instance.node_map[new_route[j+1]]) for j in range(len(new_route) - 1))
                if new_distance < best_distance:
                    best_distance = new_distance
                    best_route = new_route
    return best_route

