            continue

        best_merge_index = -1
        best_merge_distance = float('inf')
        for i, merged_route in enumerate(merged_routes):
            for j in [0, len(merged_route) - 1]:
                for k in [0, len(route) - 1]:
                    candidate_route = merged_route[:j+1] + route[k:] + merged_route[j+1:]
                    if is_battery_feasible(instance, candidate_route):
                        candidate_distance = sum(distance(instance.node_map[merged_route[m]], instance.node_map[merged_route[m+1]]) for m in range(len(candidate_route) - 1))
                        if candidate_distance < best_merge_distance:
                            best_merge_distance = candidate_distance
                            best_merge_index = i
                            best_merge_candidate = candidate_route

        if best_merge_index != -1:
            merged_routes[best_merge_index] = best_merge_candidate
        else:
            merged_routes.append(route)

    return merged_routes

