                new_distance = sum(distance(instance.node_map[route1[k]], instance.node_map[route1[k+1]]) for k in range(len(route1) - 1)) + \
                               sum(distance(instance.node_map[route2[k]], instance.node_map[route2[k+1]]) for k in range(len(route2) - 1))
                if new_distance < best_distance:
