def optimize_routes(instance, routes):
    def route_cost(route):
        return sum(distance(instance.node_map[route[i]], instance.node_map[route[i+1]]) for i in range(len(route) - 1))

    def swap_and_check(route, i, j):
        new_route = route[:]
        new_route[i], new_route[j] = new_route[j], new_route[i]
        if is_battery_feasible(instance, new_route):
            return new_route, route_cost(new_route)
        return route, float('inf')

    optimized_routes = []
    for route in routes:
        if len(route) <= 3:
            optimized_routes.append(route)
            continue

        best_route = route
        best_cost = route_cost(route)

        for i in range(1, len(route) - 2):
            for j in range(i + 1, len(route) - 1):
                new_route, new_cost = swap_and_check(route, i, j)
                if new_cost < best_cost:
                    best_route = new_route
                    best_cost = new_cost

        optimized_routes.append(best_route)

    return optimized_routes

