def reinsert_charging_stations(instance, route):
    # Remove existing charging stations
    route = [node for node in route if node not in instance.station_ids]

    # Reinsert charging stations to optimize energy consumption
    for i in range(1, len(route)):
        for station_id in instance.station_ids:
            new_route = route[:i] + [station_id] + route[i:]
            if is_battery_feasible(instance, new_route):
                route = new_route
                break

    return route

def insert_charging_station(instance, route):
    for station_id in instance.station_ids:
        for i in range(1, len(route)):
            new_route = route[:i] + [station_id] + route[i:]
            states = propagate_route(instance, new_route)
            if all(state.battery_arrival >= 0 for state in states):
                return new_route
    return None

